<template><nav class="mobile-nav" aria-label="移动端导航"><RouterLink v-for="item in items" :key="item.to" :to="item.to" :class="{ on: isOn(item) }" :aria-current="isOn(item) ? 'page' : undefined"><component :is="item.icon" :size="19"/><span>{{item.label}}</span></RouterLink></nav></template>
<script setup lang="ts">import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { Sun, Utensils, BarChart3, UserRound } from 'lucide-vue-next'
// 计划与跟练归在"今日"名下：这两页是从今日首屏下钻出去的，底栏不留独立入口也不该没有归属
const items=[{to:'/dashboard',label:'今日',icon:Sun,owns:['/plan','/execution']},{to:'/meals',label:'记录',icon:Utensils},{to:'/report',label:'图表',icon:BarChart3},{to:'/settings',label:'我的',icon:UserRound,owns:['/onboarding']}]
const route=useRoute()
const path=computed(() => route.path)
const isOn=(item:{to:string;owns?:string[]}) => path.value === item.to || (item.owns || []).some(p => path.value.startsWith(p))
</script>
<style scoped>.mobile-nav{display:none}@media(max-width:767px){.mobile-nav{display:flex;position:fixed;bottom:0;left:0;right:0;height:var(--mobile-nav-height);z-index:var(--z-sticky);background:var(--surface-glass-strong);backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4);border-top:1px solid var(--color-border);justify-content:space-around;padding:6px 4px env(safe-area-inset-bottom)}.mobile-nav a{position:relative;color:var(--color-text-muted);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-width:64px;min-height:44px;font-size:11px;padding:6px 12px;border-radius:12px;transition:color var(--motion-fast),background var(--motion-fast)}.mobile-nav a::before{content:'';position:absolute;top:1px;left:50%;width:0;height:3px;border-radius:3px;transform:translateX(-50%);background:var(--color-accent);transition:width var(--motion-base) var(--easing-spring)}.mobile-nav a.on{color:var(--color-accent);background:var(--color-accent-soft);font-weight:600}.mobile-nav a.on::before{width:20px}} </style>
